        customer -> parcelTracker.webPortal "looks up the status of their parcels" "HTTPS"
        parcelTracker.webPortal -> parcelTracker.database "reads shipments from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "writes dispatch records to" "SQL"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
        parcelTracker.webPortal -> pricingLibrary "embeds"
        parcelTracker.dispatchService -> pricingLibrary "embeds"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Library" {
                background #6A737D
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}`;

